-- ============================================================================
-- 设备档案模块 增量初始化脚本（MySQL 语法，经 convert_mysql_to_sqlserver.py 转换后执行）
-- 内容：
--   1. 建表 device_archive（设备档案）
--   2. 字典：device_status 设备状态、device_type 设备类型
--   3. 菜单：设备管理 > 设备档案（含按钮权限）
--   4. 清理低代码平台自带的无用示例菜单（导航示例/组件示例/报表演示项）
-- ============================================================================

-- ----------------------------
-- 1. Table structure for device_archive 设备档案表
-- ----------------------------
DROP TABLE IF EXISTS `device_archive`;
CREATE TABLE `device_archive`  (
  `id` varchar(36) NOT NULL COMMENT '主键ID',
  `device_code` varchar(64) NULL DEFAULT NULL COMMENT '设备编号（唯一）',
  `device_name` varchar(128) NOT NULL COMMENT '设备名称',
  `device_type` varchar(32) NULL DEFAULT NULL COMMENT '设备类型（字典device_type）',
  `device_model` varchar(128) NULL DEFAULT NULL COMMENT '规格型号',
  `manufacturer` varchar(128) NULL DEFAULT NULL COMMENT '生产厂商',
  `serial_number` varchar(64) NULL DEFAULT NULL COMMENT '出厂编号',
  `purchase_date` date NULL DEFAULT NULL COMMENT '购置日期',
  `install_location` varchar(255) NULL DEFAULT NULL COMMENT '安装位置',
  `use_dept` varchar(64) NULL DEFAULT NULL COMMENT '使用部门',
  `keeper` varchar(64) NULL DEFAULT NULL COMMENT '责任人',
  `device_status` varchar(8) NULL DEFAULT '1' COMMENT '设备状态（字典device_status：1在用 2维修 3停用 4报废）',
  `remark` varchar(500) NULL DEFAULT NULL COMMENT '备注',
  `sys_org_code` varchar(64) NULL DEFAULT NULL COMMENT '所属部门编码',
  `create_by` varchar(50) NULL DEFAULT NULL COMMENT '创建人',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(50) NULL DEFAULT NULL COMMENT '更新人',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_device_archive_code`(`device_code`) USING BTREE,
  INDEX `idx_device_archive_status`(`device_status`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '设备档案表' ROW_FORMAT = DYNAMIC;

